const { useRef, useState } = React;

const PICKERS = [
  { type: "date", label: "日期", icon: icons.Calendar },
  { type: "time", label: "时间", icon: icons.Clock },
  { type: "datetime-local", label: "日期时间", icon: icons.CalendarClock },
  { type: "month", label: "月份", icon: icons.CalendarRange },
  { type: "week", label: "周", icon: icons.CalendarDays },
  { type: "color", label: "颜色", icon: icons.Palette },
  { type: "file", label: "文件", icon: icons.Paperclip },
];

const readValue = (type, input) => {
  if (type === "file") return input.files?.[0]?.name ?? "";
  return input.value;
};

const PickerField = ({ picker, value, onPick, inputRef, onChange }) => {
  const Icon = picker.icon;
  return (
    <div className="relative min-w-0">
      <button
        type="button"
        onClick={onPick}
        className="flex w-full min-w-0 items-center gap-2.5 rounded-tau-sm border border-line-1 bg-surface px-3 py-2 text-left transition-colors hover:bg-hover"
      >
        <Icon className="pointer-events-none size-4 shrink-0 text-ink-3" />
        <span className="pointer-events-none flex min-w-0 flex-1 flex-col">
          <span className="text-tau-sm text-ink-3">{picker.label}</span>
          <span className="flex min-w-0 items-center gap-1.5">
            {picker.type === "color" && value && (
              <span className="size-3 shrink-0 rounded-full border border-line-1" style={{ background: value }} />
            )}
            <span className={value ? "truncate font-tau-mono text-tau-meta text-ink-1" : "truncate text-tau-meta text-ink-3"}>
              {value || "未选择"}
            </span>
          </span>
        </span>
      </button>
      {/* 原生 input 叠在字段上但不可见，选择器面板会贴着它弹出 */}
      <input
        ref={inputRef}
        type={picker.type}
        tabIndex={-1}
        aria-hidden="true"
        onChange={onChange}
        className="pointer-events-none absolute inset-0 size-full opacity-0"
      />
    </div>
  );
};

const Component = () => {
  const inputsRef = useRef({});
  const [values, setValues] = useState({});
  const [last, setLast] = useState(null);

  const pick = type => {
    const input = inputsRef.current[type];
    const call = `input[type="${type}"].showPicker()`;
    if (typeof input.showPicker !== "function") {
      setLast({ call, ok: false, result: "当前环境不支持 showPicker" });
      return;
    }
    try {
      input.showPicker();
      setLast({ call, ok: true, result: "已唤起选择器" });
    } catch (error) {
      setLast({ call, ok: false, result: error.name });
    }
  };

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid grid-cols-1 gap-2 rounded-tau-md border border-line-1 p-3 @md:grid-cols-2 @2xl:grid-cols-3">
        {PICKERS.map(picker => (
          <PickerField
            key={picker.type}
            picker={picker}
            value={values[picker.type]}
            inputRef={node => {
              inputsRef.current[picker.type] = node;
            }}
            onPick={() => pick(picker.type)}
            onChange={event => {
              const value = readValue(picker.type, event.target);
              setValues(current => ({ ...current, [picker.type]: value }));
            }}
          />
        ))}
      </div>
      <div className="flex min-h-[28px] flex-wrap items-center gap-2">
        {last ? (
          <>
            <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
              {last.call}
            </code>
            <icons.ArrowRight className="size-3.5 shrink-0 text-ink-3" />
            <ui.Tag color={last.ok ? "green" : "red"}>{last.result}</ui.Tag>
          </>
        ) : (
          <span className="text-tau-meta text-ink-3">点击任一字段，由按钮代替 input 唤起原生选择器</span>
        )}
      </div>
    </div>
  );
};

const { useId, useRef, useState } = React;

const FRAMEWORKS = ["React", "Vue", "Angular", "Svelte", "Solid"];
const CITIES = ["北京", "上海", "广州", "深圳", "杭州", "成都"];

const callPicker = element => {
  if (typeof element.showPicker !== "function") return { ok: false, result: "当前环境不支持 showPicker" };
  try {
    element.showPicker();
    return { ok: true, result: "已展开" };
  } catch (error) {
    return { ok: false, result: error.name };
  }
};

const Panel = ({ title, code, children, result }) => (
  <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">
    <div className="flex items-center justify-between gap-2">
      <span className="font-tau-mono text-tau-meta text-ink-2">{title}</span>
      {result && <ui.Tag color={result.ok ? "green" : "red"}>{result.result}</ui.Tag>}
    </div>
    {children}
    <code className="min-w-0 self-start break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{code}</code>
  </div>
);

const FIELD =
  "h-8 min-w-0 flex-1 rounded-tau-sm border border-line-1 bg-surface px-2.5 text-tau-body text-ink-1 outline-none focus:border-accent";

const Component = () => {
  const listId = useId();
  const selectRef = useRef(null);
  const inputRef = useRef(null);
  const [selectValue, setSelectValue] = useState("");
  const [inputValue, setInputValue] = useState("");
  const [selectResult, setSelectResult] = useState(null);
  const [inputResult, setInputResult] = useState(null);

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-2">
        <Panel title="<select>" code="select.showPicker()" result={selectResult}>
          <div className="flex items-center gap-2">
            <select ref={selectRef} value={selectValue} onChange={event => setSelectValue(event.target.value)} className={FIELD}>
              <option value="" disabled>
                选择框架
              </option>
              {FRAMEWORKS.map(name => (
                <option key={name} value={name}>
                  {name}
                </option>
              ))}
            </select>
            <ui.Button
              variant="secondary"
              size="sm"
              icon={icons.ChevronsUpDown}
              onClick={() => setSelectResult(callPicker(selectRef.current))}
            >
              展开选项
            </ui.Button>
          </div>
          <span className="font-tau-mono text-tau-meta text-ink-3">value：{selectValue ? `"${selectValue}"` : '""'}</span>
        </Panel>
        <Panel title="<input list> + <datalist>" code="input.showPicker()" result={inputResult}>
          <div className="flex items-center gap-2">
            <input
              ref={inputRef}
              list={listId}
              value={inputValue}
              onChange={event => setInputValue(event.target.value)}
              placeholder="输入或选择城市"
              className={FIELD}
            />
            <datalist id={listId}>
              {CITIES.map(city => (
                <option key={city} value={city} />
              ))}
            </datalist>
            <ui.Button variant="secondary" size="sm" icon={icons.ListFilter} onClick={() => setInputResult(callPicker(inputRef.current))}>
              展开建议
            </ui.Button>
          </div>
          <span className="font-tau-mono text-tau-meta text-ink-3">value：{inputValue ? `"${inputValue}"` : '""'}</span>
        </Panel>
      </div>
      <span className="text-tau-meta text-ink-3">建议列表会按已输入的内容过滤，先清空输入框再展开可看到全部选项。</span>
    </div>
  );
};

