const { useEffect, useRef, useState } = React;

// 浏览器的瞬时激活（transient activation）窗口约 5 秒
const SCENARIOS = [
  { key: "click", label: "click 回调中直接调用", note: "有瞬时激活" },
  { key: "delay1", label: "点击后 1 秒再调用", note: "仍在激活窗口内", delay: 1000 },
  { key: "delay6", label: "点击后 6 秒再调用", note: "激活已过期", delay: 6000 },
  { key: "hidden", label: "目标 display: none", note: "元素未渲染" },
  { key: "disabled", label: "目标 disabled", note: "元素不可修改" },
];

const resultColor = result => (result === "已唤起" ? "green" : result === "未抛出异常" ? "orange" : "red");

const Component = () => {
  const visibleRef = useRef(null);
  const hiddenRef = useRef(null);
  const disabledRef = useRef(null);
  const timersRef = useRef(new Set());
  const [results, setResults] = useState({});
  const [pending, setPending] = useState({});
  const [log, setLog] = useState([]);

  useEffect(() => () => timersRef.current.forEach(clearTimeout), []);

  const attempt = (scenario, input) => {
    let result;
    if (typeof input.showPicker !== "function") result = "当前环境不支持 showPicker";
    else {
      try {
        input.showPicker();
        // display: none 的 input 在部分浏览器里不抛错，只是不弹出
        result = scenario.key === "hidden" ? "未抛出异常" : "已唤起";
      } catch (error) {
        result = error.name;
      }
    }
    setResults(current => ({ ...current, [scenario.key]: result }));
    setPending(current => ({ ...current, [scenario.key]: false }));
    setLog(current => [{ id: Date.now() + Math.random(), label: scenario.label, result }, ...current].slice(0, 5));
  };

  const run = scenario => {
    const input = scenario.key === "hidden" ? hiddenRef.current : scenario.key === "disabled" ? disabledRef.current : visibleRef.current;
    if (!scenario.delay) return attempt(scenario, input);
    setPending(current => ({ ...current, [scenario.key]: true }));
    const timer = setTimeout(() => {
      timersRef.current.delete(timer);
      attempt(scenario, input);
    }, scenario.delay);
    timersRef.current.add(timer);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative flex min-w-0 flex-col divide-y divide-line-2 rounded-tau-md border border-line-1">
          {SCENARIOS.map(scenario => (
            <div key={scenario.key} className="flex items-center gap-3 px-3 py-2">
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="text-tau-body text-ink-1">{scenario.label}</span>
                <span className="text-tau-sm text-ink-3">{scenario.note}</span>
              </span>
              {results[scenario.key] && !pending[scenario.key] && (
                <ui.Tag color={resultColor(results[scenario.key])} className="shrink-0">
                  {results[scenario.key]}
                </ui.Tag>
              )}
              <ui.Button
                variant="secondary"
                size="sm"
                loading={pending[scenario.key]}
                disabled={pending[scenario.key]}
                onClick={() => run(scenario)}
              >
                调用
              </ui.Button>
            </div>
          ))}
          <div className="flex items-center gap-3 px-3 py-2">
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="text-tau-body text-ink-1">跨域 iframe 内调用</span>
              <span className="text-tau-sm text-ink-3">此处无法复现，按规范：file、color 之外抛出</span>
            </span>
            <ui.Tag color="gray" className="shrink-0">
              SecurityError
            </ui.Tag>
          </div>
          {/* 三个被调用的目标：可见、display: none、disabled */}
          <input
            ref={visibleRef}
            type="date"
            tabIndex={-1}
            aria-hidden="true"
            className="pointer-events-none absolute bottom-0 left-3 h-0 w-0 opacity-0"
          />
          <input ref={hiddenRef} type="date" tabIndex={-1} aria-hidden="true" className="hidden" />
          <input
            ref={disabledRef}
            type="date"
            disabled
            tabIndex={-1}
            aria-hidden="true"
            className="pointer-events-none absolute bottom-0 left-3 h-0 w-0 opacity-0"
          />
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">调用记录</span>
          {log.length ? (
            <ol className="m-0 flex list-none flex-col gap-1.5 p-0">
              {log.map(entry => (
                <li key={entry.id} className="flex min-w-0 flex-col gap-0.5">
                  <span className="text-tau-sm text-ink-2">{entry.label} →</span>
                  <span className="min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">{entry.result}</span>
                </li>
              ))}
            </ol>
          ) : (
            <p className="m-0 text-tau-meta text-ink-3">逐个调用，对比哪些会失败</p>
          )}
        </div>
      </div>
      <code className="self-start rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
        {'input[type="date"].showPicker()'}
      </code>
    </div>
  );
};
